import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
for k in sorted(G): print(k, len(G[k]), 'x', len(G[k][0]))

import numpy as np
I=np.array(G['Demo pair 1 input']); O=np.array(G['Demo pair 1 output'])
rstarts=[0,4,8,12]; cstarts=[0,3,6]
def adj_count(threes):
    pts=threes; n=len(pts); res=0
    for k in range(n):
        for m in range(k+1,n):
            if abs(pts[k][0]-pts[m][0])+abs(pts[k][1]-pts[m][1])==1: res+=1
    return res
for bi in range(4):
    for bj in range(3):
        b=I[rstarts[bi]:rstarts[bi]+3, cstarts[bj]:cstarts[bj]+2]
        threes=[(r,c) for r in range(3) for c in range(2) if b[r,c]==3]
        print((bi,bj),'n=',len(threes),'adj=',adj_count(threes),'->',O[bi,bj])
